00061     public static function getMenuMysql()
00062     {
00063         global $bearsamppBins, $bearsamppLang, $bearsamppTools;
00064         $resultItems = $resultActions = '';
00065 
00066         $isEnabled = $bearsamppBins->getMysql()->isEnable();
00067 
00068         // Download
00069         $resultItems .= TplAestan::getItemLink( $bearsamppLang->getValue(Lang::DOWNLOAD_MORE),
00070             HttpClient::getWebsiteUrl('module/mysql', '#releases'),
00071             false,
00072             TplAestan::GLYPH_BROWSER
00073         ) . PHP_EOL;
00074 
00075         // Enable
00076         $tplEnable = TplApp::getActionMulti(
00077             self::ACTION_ENABLE, array($isEnabled ? Config::DISABLED : Config::ENABLED),
00078             array($bearsamppLang->getValue(Lang::MENU_ENABLE), $isEnabled ? TplAestan::GLYPH_CHECK : ''),
00079             false, get_called_class()
00080         );
00081         $resultItems .= $tplEnable[TplApp::SECTION_CALL] . PHP_EOL;
00082         $resultActions .= $tplEnable[TplApp::SECTION_CONTENT] . PHP_EOL;
00083 
00084         if ($isEnabled) {
00085             $resultItems .= TplAestan::getItemSeparator() . PHP_EOL;
00086 
00087             // Versions
00088             $tplVersions = TplApp::getMenu($bearsamppLang->getValue(Lang::VERSIONS), self::MENU_VERSIONS, get_called_class());
00089             $resultItems .= $tplVersions[TplApp::SECTION_CALL] . PHP_EOL;
00090             $resultActions .= $tplVersions[TplApp::SECTION_CONTENT] . PHP_EOL;
00091 
00092             // Service
00093             $tplService = TplApp::getMenu($bearsamppLang->getValue(Lang::SERVICE), self::MENU_SERVICE, get_called_class());
00094             $resultItems .= $tplService[TplApp::SECTION_CALL] . PHP_EOL;
00095             $resultActions .= $tplService[TplApp::SECTION_CONTENT] . PHP_EOL;
00096 
00097             // Debug
00098             $tplDebug = TplApp::getMenu($bearsamppLang->getValue(Lang::DEBUG), self::MENU_DEBUG, get_called_class());
00099             $resultItems .= $tplDebug[TplApp::SECTION_CALL] . PHP_EOL;
00100             $resultActions .= $tplDebug[TplApp::SECTION_CONTENT];
00101 
00102             // Console
00103             $resultItems .= TplAestan::getItemPowerShell(
00104                 $bearsamppLang->getValue(Lang::CONSOLE),
00105                 TplAestan::GLYPH_POWERSHELL,
00106                 null,
00107                 $bearsamppTools->getPowerShell()->getTabTitleMysql(),
00108                 Path::getModuleSymlinkPath($bearsamppBins->getMysql()),
00109                 null
00110             ) . PHP_EOL;
00111 
00112             // Conf
00113             $resultItems .= TplAestan::getItemNotepad(basename($bearsamppBins->getMysql()->getConf()), $bearsamppBins->getMysql()->getConf()) . PHP_EOL;
00114 
00115             // Errors log
00116             $resultItems .= TplAestan::getItemNotepad($bearsamppLang->getValue(Lang::MENU_ERROR_LOGS), $bearsamppBins->getMysql()->getErrorLog()) . PHP_EOL;
00117         }
00118 
00119         return $resultItems . PHP_EOL . $resultActions;
00120     }
