00131     public static function getMenuMysqlVersions()
00132     {
00133         global $bearsamppBins;
00134         $items = '';
00135         $actions = '';
00136 
00137         foreach ($bearsamppBins->getMysql()->getVersionList() as $version) {
00138             $tplSwitchMysqlVersion = TplApp::getActionMulti(
00139                 self::ACTION_SWITCH_VERSION, array($version),
00140                 array($version, $version == $bearsamppBins->getMysql()->getVersion() ? TplAestan::GLYPH_CHECK : ''),
00141                 false, get_called_class()
00142             );
00143 
00144             // Item
00145             $items .= $tplSwitchMysqlVersion[TplApp::SECTION_CALL] . PHP_EOL;
00146 
00147             // Action
00148             $actions .= PHP_EOL . $tplSwitchMysqlVersion[TplApp::SECTION_CONTENT];
00149         }
00150 
00151         return $items . $actions;
00152     }
