00201     public static function getMenuMysqlService()
00202     {
00203         global $bearsamppLang, $bearsamppBins;
00204 
00205         $tplChangePort = TplApp::getActionMulti(
00206             self::ACTION_CHANGE_PORT, null,
00207             array($bearsamppLang->getValue(Lang::MENU_CHANGE_PORT), TplAestan::GLYPH_NETWORK),
00208             false, get_called_class()
00209         );
00210 
00211         $isInstalled = $bearsamppBins->getMysql()->getService()->isInstalled();
00212 
00213         $result = TplAestan::getItemActionServiceStart($bearsamppBins->getMysql()->getService()->getName()) . PHP_EOL .
00214             TplAestan::getItemActionServiceStop($bearsamppBins->getMysql()->getService()->getName()) . PHP_EOL .
00215             TplAestan::getItemActionServiceRestart($bearsamppBins->getMysql()->getService()->getName()) . PHP_EOL .
00216             TplAestan::getItemSeparator() . PHP_EOL .
00217             TplApp::getActionRun(
00218                 Action::CHECK_PORT, array($bearsamppBins->getMysql()->getName(), $bearsamppBins->getMysql()->getPort()),
00219                 array(sprintf($bearsamppLang->getValue(Lang::MENU_CHECK_PORT), $bearsamppBins->getMysql()->getPort()), TplAestan::GLYPH_LIGHT)
00220             ) . PHP_EOL .
00221             $tplChangePort[TplApp::SECTION_CALL] . PHP_EOL;
00222 
00223         $tplChangeRootPwd = null;
00224         if ($isInstalled) {
00225             $tplChangeRootPwd = TplApp::getActionMulti(
00226                 self::ACTION_CHANGE_ROOT_PWD, null,
00227                 array($bearsamppLang->getValue(Lang::MENU_CHANGE_ROOT_PWD), TplAestan::GLYPH_PASSWORD),
00228                 !$isInstalled, get_called_class()
00229             );
00230 
00231             $result .= $tplChangeRootPwd[TplApp::SECTION_CALL] . PHP_EOL;
00232         }
00233 
00234         if (!$isInstalled) {
00235             $tplInstallService = TplApp::getActionMulti(
00236                 self::ACTION_INSTALL_SERVICE, null,
00237                 array($bearsamppLang->getValue(Lang::MENU_INSTALL_SERVICE), TplAestan::GLYPH_SERVICE_INSTALL),
00238                 $isInstalled, get_called_class()
00239             );
00240 
00241             $result .= $tplInstallService[TplApp::SECTION_CALL] . PHP_EOL . PHP_EOL .
00242             $tplInstallService[TplApp::SECTION_CONTENT] . PHP_EOL;
00243         } else {
00244             $tplRemoveService = TplApp::getActionMulti(
00245                 self::ACTION_REMOVE_SERVICE, null,
00246                 array($bearsamppLang->getValue(Lang::MENU_REMOVE_SERVICE), TplAestan::GLYPH_SERVICE_REMOVE),
00247                 !$isInstalled, get_called_class()
00248             );
00249 
00250             $result .= $tplRemoveService[TplApp::SECTION_CALL] . PHP_EOL . PHP_EOL .
00251             $tplRemoveService[TplApp::SECTION_CONTENT] . PHP_EOL;
00252         }
00253 
00254         $result .= $tplChangePort[TplApp::SECTION_CONTENT] . PHP_EOL .
00255             ($tplChangeRootPwd != null ? $tplChangeRootPwd[TplApp::SECTION_CONTENT] . PHP_EOL : '');
00256 
00257         return $result;
00258     }
